@Aspect
@Component
public class ServiceExceptionHandlingAspect {

    @Pointcut("execution(* com.example.service.*.*(..))")
    private void servicePackageExecution() {}

    @Pointcut("within(com.example.service..*)")
    private void withinServicePackage() {}

    @Pointcut("args(java.lang.String, ..)")
    private void startsWithStringArg() {}

    @Pointcut("@annotation(com.example.annotation.HandleExceptions)")
    private void hasHandleExceptionsAnnotation() {}

    @Pointcut("bean(*ServiceImpl)")
    private void targetServiceBeans() {}

    @Around("servicePackageExecution() && hasHandleExceptionsAnnotation() && targetServiceBeans()")
    public Object handleServiceExceptions(ProceedingJoinPoint pjp) throws Throwable {
        try {
            return pjp.proceed();
        } catch (DataAccessException ex) {
            // Translate database exceptions to domain-specific runtime exceptions
            throw new CustomDataAccessException("Translated data error in " + pjp.getSignature(), ex);
        }
    }
}
